  function makeStep() {
    let total = 0;
    return function () {
      total = total + size;
      return total;
    };
  }

  const step = makeStep();
  const totals = [];
  for (let i = 0; i < times; i = i + 1) {
    totals.push(step());
  }
  return totals;
}

